import {updateMovement} from './movement.js';
const idle=()=>({x:0,z:0,sprint:false,sprintRequested:false,jump:false,firing:false,ads:false,crouchPressed:false,interactHeld:false,yaw:0,pitch:0});
function sessionToken(){try{const saved=sessionStorage.getItem('fusionfall-lan-token');if(saved)return saved}catch{}const bytes=new Uint8Array(16);crypto.getRandomValues(bytes);const token=Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('');try{sessionStorage.setItem('fusionfall-lan-token',token)}catch{}return token}
function predict(player,input,layout,dt,events={}){if(player.hp<=0)return;player.reloadTimer=Math.max(0,player.reloadTimer-dt);player.fireTimer=Math.max(0,player.fireTimer-dt);player.invuln=Math.max(0,player.invuln-dt);player.cooldowns=player.cooldowns.map(c=>Math.max(0,c-dt));player.energy=Math.min(100,player.energy+dt*2);updateMovement(player,input,layout,dt,events)}
export class LanClient {
 constructor(callbacks={}){this.callbacks=callbacks;this.token=sessionToken();this.connected=false;this.joined=false;this.running=false;this.id=null;this.state=null;this.lobby=null;this.history=[];this.seq=0;this.lastSend=0;this.pendingTime=0;this.pendingCrouch=false;this.rtt=0;this.receivedAt=0;this.loading=null;this.matchId=null;this.resultShown=null;this.pingTimer=setInterval(()=>{if(this.connected)this.send({type:'ping',time:performance.now()})},2000)}
 get isHost(){return !!this.id&&this.lobby?.hostId===this.id}
 async connect(mode,profile,map,options={}){if(this.connected&&this.joined)return;this.online=options.online===true;this.connectionOptions=options;const base=new URL(options.endpoint||location.origin||`${location.protocol}//${location.host}`);if(!['http:','https:'].includes(base.protocol)||base.username||base.password||location.protocol==='https:'&&base.protocol!=='https:')throw Error('Multiplayer needs an HTTPS server URL.');const socket=new WebSocket(`${base.protocol==='https:'?'wss':'ws'}://${base.host}/${this.online?'online':'lan'}`);this.socket=socket;return new Promise((resolve,reject)=>{let acknowledged=false;const timeout=setTimeout(()=>{if(!acknowledged){socket.close();reject(Error('Party server timed out. Try again.'))}},15000);socket.onopen=()=>{this.connected=true;this.send({type:mode,token:this.token,profile,map,code:options.code,roomId:options.roomId||this.roomId})};socket.onerror=()=>{if(!acknowledged)reject(Error('Cannot reach the party server. Check your connection and try again.'))};socket.onclose=()=>{clearTimeout(timeout);if(socket!==this.socket)return;this.connected=false;this.running=false;this.history=[];if(!acknowledged)reject(Error('Party connection closed.'));if(this.joined){this.callbacks.onDisconnect?.();if(this.online)this.autoReconnect()}};socket.onmessage=event=>{if(socket!==this.socket)return;try{const packet=JSON.parse(event.data);if(packet.type==='hello')return;if(packet.type==='joined'){clearTimeout(timeout);clearTimeout(this.reconnectTimer);this.reconnecting=false;acknowledged=true;this.roomId=packet.lobby.roomId;this.joined=true;if(this.online)try{sessionStorage.setItem('fusionfall-online-room',JSON.stringify({roomId:this.roomId,endpoint:base.origin}))}catch{};this.id=packet.id;this.lobby=packet.lobby;this.history=[];this.seq=0;this.callbacks.onLobby?.(packet.lobby);resolve();return}if(packet.type==='error'){if(!acknowledged){this.joined=false;reject(Error(packet.message));socket.close()}this.callbacks.onError?.(packet.message);return}if(packet.type==='pong'){this.rtt=Math.round(performance.now()-packet.time);return}if(packet.type==='lobby'){this.lobby=packet;this.callbacks.onLobby?.(packet);return}if(packet.type==='state'){this.receivedAt=performance.now();this.state=packet;const phaseChanged=this.lobby&&this.lobby.phase!==packet.phase;if(this.lobby){this.lobby.phase=packet.phase;this.lobby.hostId=packet.hostId;this.lobby.map=packet.map}if(phaseChanged)this.callbacks.onLobby?.(this.lobby);if(packet.phase==='playing'&&(!this.running||this.matchId!==packet.matchId)){this.running=true;this.matchId=packet.matchId;this.resultShown=null;this.history=[];this.seq=0;this.pendingTime=0;this.pendingCrouch=false;this.loading=Promise.resolve(this.callbacks.onMatch?.(packet)).then(()=>{this.loading=null;if(this.joined)this.deliver(this.state)}).catch(error=>{this.loading=null;this.callbacks.onError?.(error.message)});return}if(!this.loading)this.deliver(packet);return}if(packet.type==='shot'){this.callbacks.onShot?.(packet);return}if(packet.type==='event'||packet.type==='revived')this.callbacks.onEvent?.(packet)}catch(error){this.callbacks.onError?.(error.message)}}})}
 autoReconnect(){if(this.reconnecting||!this.roomId)return;this.reconnecting=true;const generation=this.reconnectGeneration||0,deadline=Date.now()+18000;let delay=500;const retry=async()=>{if(!this.reconnecting||generation!==(this.reconnectGeneration||0))return;try{await this.connect('reconnect',{},null,{...this.connectionOptions,roomId:this.roomId});this.reconnecting=false;}catch{if(generation!==(this.reconnectGeneration||0)||!this.reconnecting)return;if(Date.now()<deadline&&this.reconnecting){this.reconnectTimer=setTimeout(retry,delay);delay=Math.min(4000,delay*2)}else{this.reconnecting=false;this.callbacks.onError?.('Reconnect window expired. Ask the host for a fresh code.')}}};this.reconnectTimer=setTimeout(retry,delay)}
 deliver(packet){if(!packet)return;this.callbacks.onState?.(packet);if(packet.phase==='result'&&this.matchId===packet.matchId&&this.resultShown!==packet.matchId){this.running=false;this.resultShown=packet.matchId;this.callbacks.onResult?.(packet)}}
 send(packet){if(this.socket?.readyState===WebSocket.OPEN){this.socket.send(JSON.stringify(packet));return true}return false}
 action(action,values={}){if(this.joined&&this.connected&&this.running)this.send({type:'action',action,matchId:this.matchId,...values})}
 start(){if(this.isHost)this.send({type:'start'})}
 updateProfile(profile){if(this.joined&&this.connected&&this.lobby?.phase!=='playing')this.send({type:'profile',profile})}
 invite(){if(this.isHost&&this.online)this.send({type:'invite'})}
 chooseMap(map){if(this.isHost)this.send({type:'map',map})}
 leave(){this.reconnecting=false;this.reconnectGeneration=(this.reconnectGeneration||0)+1;clearTimeout(this.reconnectTimer);if(this.online)try{sessionStorage.removeItem('fusionfall-online-room')}catch{}this.roomId=null;this.send({type:'leave'});this.joined=false;this.running=false;this.connected=false;this.state=null;this.history=[];this.matchId=null;this.id=null;this.socket?.close();this.socket=null}
 frame(sim,dt,input,active){if(!this.joined||!this.running||!this.connected)return;const stale=performance.now()-this.receivedAt>1200,value=active&&!stale?{x:input.x,z:input.z,sprint:input.sprint,sprintRequested:input.sprintRequested,jump:input.jump,crouchPressed:input.crouchPressed,firing:input.firing,ads:input.ads,yaw:input.yaw,pitch:input.pitch,interactHeld:input.interactHeld}:idle();this.pendingTime+=dt;this.pendingCrouch||=!!value.crouchPressed;const now=performance.now();if(now-this.lastSend>=14&&this.socket.bufferedAmount<256000){value.crouchPressed=this.pendingCrouch;const seq=++this.seq;this.send({type:'input',seq,matchId:this.matchId,input:value});this.history.push({seq,dt:Math.min(.05,this.pendingTime),input:{...value}});this.history=this.history.slice(-120);this.pendingTime=0;this.pendingCrouch=false;this.lastSend=now}if(active&&!stale)predict(sim.player,{...input},sim.layout,dt,sim.events);sim.elapsed+=dt}
 apply(snapshot,sim,world){if(!snapshot||!sim.player)return;const me=snapshot.players.find(p=>p.id===this.id);if(!me)return;const oldNano=sim.player.nano,oldGun=sim.equipped?.id;Object.assign(sim.player,me);sim.loadout=me.profile.loadout;sim.fieldKit=me.profile.kit||sim.fieldKit;this.history=this.history.filter(record=>record.seq>me.inputAck);for(const record of this.history)predict(sim.player,record.input,sim.layout,record.dt);sim.elapsed=snapshot.elapsed;sim.wave=snapshot.wave;sim.waveKind=snapshot.waveKind;sim.intermission=snapshot.intermission;sim.power=snapshot.power;sim.extraction=snapshot.extraction;sim.box=snapshot.box;sim.spawnQueue=Array.from({length:snapshot.queue},()=>snapshot.map);if(Object.entries(snapshot.unlocked).some(([key,value])=>sim.layout.unlocked[key]!==value)){sim.layout.unlocked={...snapshot.unlocked};sim.layout.refresh()}const reconcile=(records,current,create)=>{const old=new Map(current.map(r=>[r.id,r])),seen=new Set();const result=records.map(record=>{seen.add(record.id);let existing=old.get(record.id);if(existing)Object.assign(existing,record);else{existing={...record};create(existing)}return existing});for(const record of current)if(!seen.has(record.id)){record.dead=true;record.deathTime??=snapshot.elapsed-3}return result};sim.enemies=reconcile(snapshot.enemies,sim.enemies,e=>{if(!e.dead||snapshot.elapsed-e.deathTime<2.6)world.addEnemy(e)});sim.projectiles=reconcile(snapshot.projectiles,sim.projectiles,p=>world.addProjectile(p));sim.drops=reconcile(snapshot.drops,sim.drops,d=>world.addDrop(d));if(oldGun!==sim.equipped.id)world.weapon(sim.equipped.id);if(oldNano!==me.nano)world.nano(me.nano);world.setPeers(snapshot.players,this.id);}
}
